import markdown.inlinepatterns as ip
import markdown.treeprocessors as tp
import markdown

md = markdown.Markdown()
proc = tp.InlineProcessor(md)
proc.stashed_nodes = {}

class P(ip.BacktickInlineProcessor):
    def __init__(self):
        super().__init__(ip.BACKTICK_RE)
        self.calls = []
    def handleMatch(self, m, data):
        r = super().handleMatch(m, data)
        self.calls.append((m.span(0), data[m.start(0):m.end(0)], r))
        return r

p = P()
apply = getattr(tp.InlineProcessor, '_InlineProcessor__applyPattern')
data = 'Backtick: `` \\` ``'
startIndex = 0
count = 0
while True:
    data, matched, startIndex = apply(proc, p, data, 0, startIndex)
    count += 1
    print('iter', count, 'matched' if matched else 'no match', 'startIndex', startIndex, 'data', repr(data))
    if not matched or count > 20:
        break
for c in p.calls: print(c)
